/* ============================================================
   KIMETSU: NIGHTMARE SHIFT
   Visual system: ink, bone, old paper, blood red, wisteria teal
   ============================================================ */

@import '@fontsource/bebas-neue/400.css';
@import '@fontsource/cormorant-garamond/400.css';
@import '@fontsource/cormorant-garamond/500.css';
@import '@fontsource/cormorant-garamond/600.css';
@import '@fontsource/cormorant-garamond/400-italic.css';
@import '@fontsource/ibm-plex-mono/300.css';
@import '@fontsource/ibm-plex-mono/400.css';
@import '@fontsource/ibm-plex-mono/500.css';

:root {
  --ink: #080a0a;
  --ink-2: #0e1111;
  --ink-3: #161a19;
  --bone: #e9e1cf;
  --bone-dim: #b6ad9c;
  --paper: #cfc4ac;
  --red: #bd1823;
  --red-bright: #e22430;
  --red-deep: #6c0d13;
  --teal: #6d9a92;
  --teal-dim: #3e5d58;
  --gold: #c9ab6e;
  --line: rgba(233, 225, 207, 0.16);
  --line-strong: rgba(233, 225, 207, 0.32);
  --serif: 'Cormorant Garamond', 'Times New Roman', serif;
  --display: 'Bebas Neue', 'Arial Narrow', sans-serif;
  --mono: 'IBM Plex Mono', 'Courier New', monospace;
  --ease: cubic-bezier(0.22, 0.8, 0.22, 1);
}

* { box-sizing: border-box; }
html, body { width: 100%; height: 100%; margin: 0; background: var(--ink); color: var(--bone); }
body {
  font-family: var(--mono);
  overflow: hidden;
  -webkit-tap-highlight-color: transparent;
  user-select: none;
  touch-action: none;
}
button, input, select { font: inherit; color: inherit; }
button { border: 0; background: none; cursor: pointer; }
button:focus-visible { outline: 1px solid var(--gold); outline-offset: 3px; }
::selection { background: var(--red); color: var(--bone); }

#app, #webgl {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
}
#webgl {
  display: block;
  z-index: 0;
  transition: filter 0.45s var(--ease), opacity 0.6s var(--ease);
  cursor: grab;
  touch-action: none;
}
#webgl.is-dragging { cursor: grabbing; }
#webgl.feed-mode {
  filter: grayscale(0.93) sepia(0.18) contrast(1.23) brightness(0.72);
}
#webgl.menu-mode { filter: brightness(0.82) contrast(1.05) saturate(0.8); }

#atmosphere {
  position: fixed;
  inset: 0;
  z-index: 2;
  pointer-events: none;
}
.vignette {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse at 50% 44%, transparent 32%, rgba(3, 4, 4, 0.32) 68%, rgba(2, 3, 3, 0.82) 100%),
    linear-gradient(180deg, rgba(2, 3, 3, 0.52), transparent 20%, transparent 75%, rgba(2, 3, 3, 0.55));
  mix-blend-mode: multiply;
}
.grain {
  position: absolute;
  inset: -40%;
  opacity: 0.052;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
  animation: grainShift 0.22s steps(2) infinite;
  will-change: transform;
}
@keyframes grainShift {
  0% { transform: translate(0, 0); }
  25% { transform: translate(-2%, 1.5%); }
  50% { transform: translate(1%, -1%); }
  75% { transform: translate(-1.5%, -2%); }
  100% { transform: translate(1.5%, 2%); }
}
.letterbox { position: absolute; left: 0; right: 0; height: 0; background: #030404; }
.letterbox.top { top: 0; }
.letterbox.bottom { bottom: 0; }

/* ============================ SCREENS ============================ */
.screen {
  position: fixed;
  inset: 0;
  z-index: 10;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity 0.55s var(--ease), visibility 0.55s;
  overflow: hidden;
}
.screen.is-active {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
}
.is-hidden { display: none !important; }

#loading-screen {
  z-index: 100;
  background: #060808;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
}
#loading-screen .loader-mark { width: 104px; height: 104px; position: relative; display: grid; place-items: center; margin-bottom: 16px; }
#loading-screen .jp { font-family: var(--serif); font-size: 52px; color: var(--red); line-height: 1; text-shadow: 0 0 40px rgba(189, 24, 35, 0.7); }
.loader-ring { position: absolute; inset: 0; border: 1px solid var(--line); border-top-color: var(--red); border-radius: 50%; animation: spin 1.8s linear infinite; }
@keyframes spin { to { transform: rotate(360deg); } }
.loading-copy { font-size: 10px; letter-spacing: 0.24em; color: var(--bone-dim); margin: 4px 0 10px; }
.ellipsis { display: inline-block; width: 18px; overflow: hidden; vertical-align: bottom; animation: dots 1.2s steps(4) infinite; }
@keyframes dots { from { width: 0; } to { width: 18px; } }
.loading-line { width: min(280px, 60vw); height: 1px; background: var(--line); overflow: hidden; }
.loading-line i { display: block; width: 40%; height: 100%; background: var(--red); animation: load 1.4s var(--ease) infinite; }
@keyframes load { from { transform: translateX(-110%); } to { transform: translateX(360%); } }

.eyebrow {
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.32em;
  text-transform: uppercase;
  color: var(--teal);
}
.eyebrow.error { color: var(--red-bright); }
.eyebrow.dawn { color: var(--gold); }

/* ============================ TITLE ============================ */
.title-screen {
  padding: clamp(20px, 2.4vw, 38px) clamp(24px, 4.5vw, 74px) clamp(16px, 2vw, 28px);
  display: flex;
  flex-direction: column;
  background:
    linear-gradient(90deg, rgba(4, 6, 6, 0.92) 0%, rgba(4, 6, 6, 0.74) 38%, rgba(4, 6, 6, 0.18) 68%, rgba(4, 6, 6, 0.12) 100%),
    linear-gradient(180deg, rgba(4, 6, 6, 0.5), transparent 24%, transparent 70%, rgba(4, 6, 6, 0.9));
}
.title-screen::before {
  content: '';
  position: absolute;
  left: 0; top: 0; bottom: 0;
  width: 44%;
  background: radial-gradient(circle at 22% 55%, rgba(120, 15, 22, 0.2), transparent 58%);
  pointer-events: none;
}
.title-screen::after {
  content: '鬼';
  position: absolute;
  right: 8vw;
  top: 4vh;
  font-family: var(--serif);
  font-size: clamp(260px, 38vw, 620px);
  line-height: 0.8;
  color: rgba(233, 225, 207, 0.022);
  pointer-events: none;
}
.title-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  position: relative;
  z-index: 2;
  border-bottom: 1px solid var(--line);
  padding-bottom: 13px;
}
.brand-small { display: flex; align-items: center; gap: 11px; font-size: 8px; line-height: 1.5; letter-spacing: 0.2em; color: var(--bone-dim); }
.brand-slash { width: 3px; height: 28px; background: var(--red); display: inline-block; transform: skewX(-18deg); box-shadow: 6px 0 0 rgba(189, 24, 35, 0.28); }
.header-right { display: flex; align-items: center; gap: 14px; font-family: var(--mono); font-size: 8px; letter-spacing: 0.18em; color: var(--bone-dim); }
.header-divider { width: 32px; height: 1px; background: var(--line-strong); }
#title-clock { color: var(--bone); letter-spacing: 0.12em; font-size: 11px; }
.live-dot { width: 5px; height: 5px; border-radius: 50%; background: var(--red); box-shadow: 0 0 8px var(--red); animation: livePulse 2.3s infinite; }
@keyframes livePulse { 0%, 100% { opacity: 0.45; } 50% { opacity: 1; } }

.title-layout {
  flex: 1;
  display: grid;
  grid-template-columns: minmax(0, 1fr) clamp(190px, 19vw, 278px);
  gap: 50px;
  align-items: center;
  position: relative;
  z-index: 2;
  min-height: 0;
}
.title-main { padding-top: 14px; max-width: 760px; position: relative; }
.kanji-vertical {
  position: absolute;
  left: -52px;
  top: 24px;
  writing-mode: vertical-rl;
  font-family: var(--serif);
  font-size: 12px;
  letter-spacing: 0.28em;
  color: rgba(233, 225, 207, 0.32);
  border-left: 1px solid var(--line);
  padding-left: 12px;
}
.title-eyebrow { margin: 0 0 12px 4px; color: var(--gold); font-size: 8px; letter-spacing: 0.44em; }
.game-title { margin: 0; display: flex; flex-direction: column; position: relative; }
.title-k {
  font-family: var(--display);
  font-weight: 400;
  font-size: clamp(82px, 12.2vw, 208px);
  line-height: 0.76;
  letter-spacing: 0.005em;
  color: var(--bone);
  text-shadow: 0 4px 60px rgba(0, 0, 0, 0.85);
}
.title-nightmare {
  font-family: var(--display);
  font-size: clamp(26px, 4.3vw, 68px);
  letter-spacing: 0.18em;
  line-height: 1;
  color: var(--bone-dim);
  margin-top: 10px;
  padding-left: 5px;
  display: flex;
  align-items: center;
  gap: 0.24em;
}
.title-nightmare em { font-style: normal; color: var(--red-bright); text-shadow: 0 0 26px rgba(226, 36, 48, 0.25); }
.title-rule { display: flex; align-items: center; gap: 12px; margin: 18px 0 14px; }
.title-rule span { display: block; height: 1px; flex: 1; max-width: 420px; background: linear-gradient(90deg, var(--red) 0%, rgba(189, 24, 35, 0.15) 65%, transparent); }
.title-rule b { font-family: var(--serif); font-weight: 400; font-size: 12px; color: var(--red-bright); border: 1px solid rgba(189, 24, 35, 0.55); width: 23px; height: 23px; display: grid; place-items: center; transform: rotate(45deg); }
.title-rule b::first-letter { transform: rotate(-45deg); }
.title-tagline { font-family: var(--serif); font-size: clamp(15px, 1.4vw, 20px); line-height: 1.6; letter-spacing: 0.035em; color: var(--bone-dim); margin: 0 0 26px 4px; }
.title-tagline::first-line { color: var(--bone); }

.main-nav { display: flex; flex-direction: column; width: min(100%, 520px); border-top: 1px solid var(--line); }
.menu-button {
  position: relative;
  display: flex;
  align-items: center;
  gap: 18px;
  text-align: left;
  border-bottom: 1px solid var(--line);
  padding: 14px 12px 14px 8px;
  overflow: hidden;
  transition: color 0.3s, padding 0.35s var(--ease), background 0.35s;
}
.menu-button::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, rgba(189, 24, 35, 0.92), rgba(124, 12, 19, 0.4));
  transform: translateX(-101%);
  transition: transform 0.42s var(--ease);
  z-index: 0;
}
.menu-button > * { position: relative; z-index: 1; }
.menu-button:hover, .menu-button:focus-visible { padding-left: 18px; }
.menu-button:hover::before, .menu-button:focus-visible::before { transform: translateX(0); }
.menu-index { font-size: 8px; letter-spacing: 0.1em; color: var(--teal); width: 22px; flex: 0 0 auto; transition: color 0.3s; }
.menu-button:hover .menu-index { color: var(--bone); }
.menu-label { flex: 1; display: flex; flex-direction: column; gap: 3px; }
.menu-label strong { font-family: var(--display); font-weight: 400; font-size: clamp(20px, 1.9vw, 29px); line-height: 1; letter-spacing: 0.09em; color: var(--bone); transition: color 0.3s; }
.menu-label small { font-size: 7px; letter-spacing: 0.2em; color: var(--bone-dim); transition: color 0.3s; }
.menu-button:hover .menu-label small { color: rgba(233, 225, 207, 0.8); }
.menu-arrow { font-size: 18px; color: rgba(233, 225, 207, 0.35); transition: color 0.3s, transform 0.3s; }
.menu-button:hover .menu-arrow { color: var(--bone); transform: translate(3px, -3px); }
.menu-button-primary .menu-index { color: var(--red-bright); }
.menu-row { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; border-bottom: 1px solid var(--line); }
.menu-row .menu-button { border-bottom: 0; padding: 11px 8px; }
.menu-row .menu-button:first-child { border-right: 1px solid var(--line); }
.menu-row .menu-label strong { font-size: 15px; letter-spacing: 0.14em; color: var(--bone-dim); }
.menu-row .menu-button:hover .menu-label strong { color: var(--bone); }
.menu-button-small { justify-content: center; }

.title-aside {
  border-left: 1px solid var(--line);
  padding-left: clamp(22px, 2.2vw, 38px);
  display: flex;
  flex-direction: column;
  gap: clamp(20px, 3vh, 34px);
  justify-content: center;
  position: relative;
  align-self: stretch;
  padding-top: 5vh;
}
.wisteria-stamp { width: clamp(96px, 9vw, 138px); height: clamp(96px, 9vw, 138px); color: var(--red); position: relative; opacity: 0.9; }
.wisteria-stamp svg { width: 100%; height: 100%; animation: stampBreathe 8s ease-in-out infinite; }
@keyframes stampBreathe { 0%, 100% { opacity: 0.65; transform: rotate(-2deg); } 50% { opacity: 1; transform: rotate(0deg); } }
.wisteria-stamp span { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; font-family: var(--serif); font-size: 19px; line-height: 1.1; text-align: center; letter-spacing: 0.1em; color: var(--red-bright); }
.aside-meta p { font-family: var(--serif); font-size: clamp(16px, 1.45vw, 21px); line-height: 1.5; color: var(--bone-dim); margin: 8px 0 0; }
.aside-meta p b { color: var(--bone); font-weight: 500; }
.aside-stats { display: flex; gap: 17px; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); padding: 14px 0; }
.aside-stats div { display: flex; flex-direction: column; gap: 4px; }
.aside-stats span { font-family: var(--display); font-size: 25px; line-height: 1; color: var(--bone); letter-spacing: 0.05em; }
.aside-stats small { font-size: 6px; letter-spacing: 0.18em; color: var(--bone-dim); }
.content-note { font-size: 6px; line-height: 1.9; letter-spacing: 0.1em; color: rgba(182, 173, 156, 0.58); margin: 0; }
.title-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-top: 1px solid var(--line);
  padding-top: 12px;
  font-size: 6px;
  letter-spacing: 0.18em;
  color: rgba(182, 173, 156, 0.54);
  position: relative;
  z-index: 2;
}
.footer-tip { color: var(--bone-dim); display: flex; align-items: center; gap: 10px; }
.footer-tip i { width: 28px; height: 1px; background: var(--red); display: inline-block; }

/* ============================ PANEL SCREENS ============================ */
.panel-screen {
  background:
    radial-gradient(ellipse at 78% 20%, rgba(189, 24, 35, 0.08), transparent 48%),
    linear-gradient(180deg, rgba(6, 8, 8, 0.94), rgba(6, 8, 8, 0.97));
  backdrop-filter: blur(14px);
  overflow-y: auto;
  padding: clamp(18px, 3vw, 46px) clamp(18px, 5vw, 76px);
}
.panel-screen::before {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  background-image: linear-gradient(rgba(233, 225, 207, 0.018) 1px, transparent 1px);
  background-size: 100% 34px;
}
.panel-shell { max-width: 1280px; margin: 0 auto; min-height: 100%; display: flex; flex-direction: column; position: relative; }
.panel-shell.narrow { max-width: 820px; }
.panel-shell.wide { max-width: 1420px; }
.panel-header {
  display: grid;
  grid-template-columns: 190px 1fr 70px;
  align-items: center;
  border-bottom: 1px solid var(--line-strong);
  padding-bottom: 18px;
  margin-bottom: 24px;
  flex-shrink: 0;
}
.back-button { display: flex; align-items: center; gap: 10px; color: var(--bone-dim); font-size: 8px; letter-spacing: 0.2em; text-align: left; transition: color 0.25s; }
.back-button:hover { color: var(--bone); }
.panel-heading { text-align: center; }
.panel-heading h2 { font-family: var(--display); font-weight: 400; font-size: clamp(26px, 3.3vw, 48px); letter-spacing: 0.13em; line-height: 1; margin: 6px 0 0; color: var(--bone); }
.panel-number { font-family: var(--display); font-size: 42px; color: rgba(233, 225, 207, 0.1); text-align: right; line-height: 1; }
.night-difficulty { display: flex; align-items: center; justify-content: center; gap: 25px; margin: 0 0 25px; flex-shrink: 0; }
.label { font-size: 7px; letter-spacing: 0.28em; color: var(--bone-dim); }
.segmented { display: flex; border: 1px solid var(--line); }
.segmented button { padding: 10px 19px; font-size: 8px; letter-spacing: 0.13em; color: var(--bone-dim); border-right: 1px solid var(--line); display: flex; align-items: center; gap: 7px; transition: background 0.25s, color 0.25s; }
.segmented button:last-child { border-right: 0; }
.segmented button small { font-size: 6px; opacity: 0.5; }
.segmented button:hover { color: var(--bone); background: rgba(233, 225, 207, 0.04); }
.segmented button.is-active { background: var(--red); color: var(--bone); }
.segmented.small button { padding: 8px 14px; }

.night-cards { display: grid; grid-template-columns: repeat(5, 1fr); gap: 12px; margin-bottom: 28px; flex: 1; }
.night-card {
  position: relative;
  min-height: clamp(260px, 48vh, 430px);
  border: 1px solid var(--line);
  padding: 22px 17px 16px;
  text-align: left;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  overflow: hidden;
  background: linear-gradient(180deg, rgba(233, 225, 207, 0.03), rgba(0, 0, 0, 0.22));
  transition: border-color 0.35s, transform 0.35s var(--ease), background 0.35s;
}
.night-card::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 50% 88%, rgba(189, 24, 35, 0.22), transparent 58%);
  opacity: 0;
  transition: opacity 0.4s;
}
.night-card::after {
  content: attr(data-night);
  position: absolute;
  right: -14px;
  top: 14px;
  font-family: var(--display);
  font-size: 152px;
  line-height: 1;
  color: rgba(233, 225, 207, 0.033);
  pointer-events: none;
}
.night-card:hover:not(:disabled) { border-color: rgba(189, 24, 35, 0.7); transform: translateY(-5px); }
.night-card:hover:not(:disabled)::before { opacity: 1; }
.night-card.is-selected { border-color: var(--red); background: linear-gradient(180deg, rgba(189, 24, 35, 0.13), rgba(0, 0, 0, 0.25)); }
.night-card.is-selected .night-card-index { color: var(--red-bright); }
.night-card:disabled { opacity: 0.38; cursor: not-allowed; }
.night-card-top { display: flex; align-items: center; justify-content: space-between; position: relative; z-index: 1; }
.night-card-index { font-family: var(--display); font-size: 22px; letter-spacing: 0.08em; color: var(--bone-dim); }
.night-card-status { font-size: 6px; letter-spacing: 0.15em; color: var(--teal); border: 1px solid rgba(109, 154, 146, 0.3); padding: 3px 6px; }
.night-card-status.cleared { color: var(--gold); border-color: rgba(201, 171, 110, 0.35); }
.night-card-status.locked { color: var(--bone-dim); border-color: var(--line); }
.night-card-mid { position: relative; z-index: 1; display: flex; flex-direction: column; gap: 13px; margin: 20px 0; }
.night-card-mid h3 { font-family: var(--display); font-weight: 400; font-size: clamp(27px, 2.8vw, 43px); line-height: 0.9; letter-spacing: 0.04em; margin: 0; }
.night-card-mid p { font-family: var(--serif); font-size: 13px; line-height: 1.45; color: var(--bone-dim); margin: 0; min-height: 54px; }
.night-card-subjects { display: flex; flex-wrap: wrap; gap: 4px; }
.night-card-subjects span { font-size: 5.5px; letter-spacing: 0.08em; padding: 3px 5px; border: 1px solid var(--line); color: var(--bone-dim); }
.night-card-foot { position: relative; z-index: 1; border-top: 1px solid var(--line); padding-top: 11px; display: flex; justify-content: space-between; align-items: center; font-size: 6px; letter-spacing: 0.15em; color: var(--bone-dim); }
.night-card-foot i { width: 5px; height: 5px; border-radius: 50%; background: var(--red); box-shadow: 0 0 7px rgba(189, 24, 35, 0.6); }
.night-card.is-locked .night-card-foot i { background: #444; box-shadow: none; }
.panel-footer { border-top: 1px solid var(--line); padding-top: 18px; display: flex; align-items: center; justify-content: space-between; gap: 30px; flex-shrink: 0; }
.panel-footer p { font-family: var(--serif); color: var(--bone-dim); font-size: 14px; margin: 0; max-width: 720px; }
.action-button {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 30px;
  padding: 15px 25px;
  background: var(--red);
  color: var(--bone);
  font-family: var(--display);
  font-size: 22px;
  letter-spacing: 0.13em;
  overflow: hidden;
  transition: background 0.3s, transform 0.25s;
  white-space: nowrap;
}
.action-button::after { content: ''; position: absolute; inset: 0; background: linear-gradient(100deg, transparent 35%, rgba(255, 255, 255, 0.14), transparent 65%); transform: translateX(-110%); transition: transform 0.55s var(--ease); }
.action-button:hover { background: var(--red-bright); transform: translateY(-2px); }
.action-button:hover::after { transform: translateX(110%); }
.action-button span { font-family: var(--mono); font-size: 14px; }
.action-button:disabled { opacity: 0.35; pointer-events: none; }
.text-button { font-size: 7px; letter-spacing: 0.2em; color: var(--bone-dim); border-bottom: 1px solid var(--line); padding: 8px 0; transition: color 0.25s, border-color 0.25s; }
.text-button:hover { color: var(--bone); border-color: var(--bone); }
.text-button.danger { color: var(--red); }
.text-button.danger:hover { color: var(--red-bright); }

/* ============================ CUSTOM ============================ */
.custom-layout { display: grid; grid-template-columns: minmax(0, 1fr) 300px; gap: clamp(24px, 4vw, 62px); flex: 1; align-items: start; }
.custom-sliders { border-top: 1px solid var(--line); }
.slider-row { display: grid; grid-template-columns: 1fr 2.2fr 42px; gap: 18px; align-items: center; padding: 14px 4px; border-bottom: 1px solid var(--line); }
.slider-id { display: flex; align-items: center; gap: 12px; }
.slider-avatar { width: 34px; height: 34px; border-radius: 50%; border: 1px solid var(--line-strong); display: grid; place-items: center; font-family: var(--serif); font-size: 12px; color: var(--bone); position: relative; background: rgba(233, 225, 207, 0.04); }
.slider-avatar::after { content: ''; position: absolute; inset: 3px; border: 1px solid var(--line); border-radius: 50%; }
.slider-name { display: flex; flex-direction: column; gap: 2px; }
.slider-name b { font-family: var(--display); font-weight: 400; font-size: 16px; letter-spacing: 0.09em; }
.slider-name small { font-size: 6px; letter-spacing: 0.1em; color: var(--bone-dim); }
input[type=range] {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 20px;
  background: transparent;
  cursor: pointer;
}
input[type=range]::-webkit-slider-runnable-track { height: 2px; background: linear-gradient(90deg, var(--red) var(--val, 50%), rgba(233, 225, 207, 0.14) var(--val, 50%)); }
input[type=range]::-moz-range-track { height: 2px; background: rgba(233, 225, 207, 0.14); }
input[type=range]::-moz-range-progress { height: 2px; background: var(--red); }
input[type=range]::-webkit-slider-thumb { -webkit-appearance: none; width: 12px; height: 12px; background: var(--bone); border: 2px solid var(--red); transform: translateY(-5px) rotate(45deg); }
input[type=range]::-moz-range-thumb { width: 9px; height: 9px; background: var(--bone); border: 2px solid var(--red); border-radius: 0; transform: rotate(45deg); }
.slider-value { font-family: var(--display); font-size: 23px; color: var(--bone); text-align: right; }
.slider-value small { font-family: var(--mono); font-size: 7px; color: var(--bone-dim); }
.custom-side { border-left: 1px solid var(--line); padding-left: clamp(20px, 3vw, 34px); display: flex; flex-direction: column; gap: 20px; }
.aggression-readout { display: flex; flex-direction: column; border-bottom: 1px solid var(--line); padding-bottom: 15px; }
.aggression-readout span { font-family: var(--display); font-size: 78px; line-height: 0.85; color: var(--red-bright); }
.aggression-readout small { font-size: 6px; letter-spacing: 0.18em; color: var(--bone-dim); margin-top: 6px; }
.preset-buttons { display: flex; flex-direction: column; }
.preset-buttons button { text-align: left; padding: 9px 0; border-bottom: 1px solid var(--line); font-family: var(--serif); font-size: 16px; color: var(--bone-dim); transition: color 0.2s, padding 0.2s; }
.preset-buttons button:hover { color: var(--bone); padding-left: 7px; }
.custom-tip { border: 1px solid var(--line); padding: 14px; }
.custom-tip b { font-size: 7px; letter-spacing: 0.2em; color: var(--gold); }
.custom-tip p { font-family: var(--serif); font-size: 14px; line-height: 1.45; color: var(--bone-dim); margin: 6px 0 0; }
.custom-difficulty { display: flex; align-items: center; justify-content: space-between; font-size: 7px; letter-spacing: 0.2em; color: var(--bone-dim); }
.custom-difficulty select { background: var(--ink-2); border: 1px solid var(--line); color: var(--bone); padding: 9px 10px; font-size: 8px; letter-spacing: 0.1em; outline: none; }

/* ============================ OPTIONS ============================ */
.options-list { border-top: 1px solid var(--line); }
.range-row { display: grid; grid-template-columns: 1fr 1.7fr 42px; gap: 24px; align-items: center; padding: 20px 3px; border-bottom: 1px solid var(--line); }
.range-row span, .toggle-row > span { display: flex; flex-direction: column; gap: 4px; }
.range-row b, .toggle-row b { font-family: var(--display); font-weight: 400; font-size: 17px; letter-spacing: 0.09em; }
.range-row small, .toggle-row small { font-size: 7px; letter-spacing: 0.05em; color: var(--bone-dim); }
.range-row output { font-family: var(--display); font-size: 22px; text-align: right; }
.toggle-row { display: flex; align-items: center; justify-content: space-between; gap: 20px; padding: 20px 3px; border-bottom: 1px solid var(--line); }
.switch { width: 74px; height: 30px; border: 1px solid var(--line-strong); display: flex; align-items: center; padding: 3px 8px; gap: 9px; color: var(--bone-dim); font-size: 7px; letter-spacing: 0.1em; transition: border-color 0.25s; flex-shrink: 0; }
.switch i { width: 9px; height: 9px; border-radius: 50%; background: var(--bone-dim); transition: background 0.25s, box-shadow 0.25s; }
.switch[aria-checked=true] { border-color: rgba(189, 24, 35, 0.7); color: var(--bone); }
.switch[aria-checked=true] i { background: var(--red-bright); box-shadow: 0 0 9px rgba(226, 36, 48, 0.7); }
.options-actions { display: flex; align-items: center; justify-content: space-between; padding: 25px 3px; }
#save-status { font-size: 7px; color: var(--teal); letter-spacing: 0.08em; }

/* ============================ HOW TO ============================ */
.manual-layout { display: grid; grid-template-columns: minmax(300px, 0.85fr) minmax(400px, 1.3fr); gap: clamp(30px, 4vw, 70px); flex: 1; }
.manual-controls { display: flex; flex-direction: column; gap: 22px; }
.control-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 1px; background: var(--line); border: 1px solid var(--line); }
.control-grid > div { background: var(--ink); padding: 12px; display: flex; flex-wrap: wrap; align-items: center; gap: 6px; }
.control-grid span { width: 100%; font-family: var(--serif); font-size: 13px; color: var(--bone-dim); margin-top: 3px; }
kbd { font-family: var(--mono); font-size: 7px; border: 1px solid var(--line-strong); color: var(--bone); padding: 4px 6px; background: rgba(233, 225, 207, 0.05); min-width: 24px; text-align: center; }
.touch-note { font-family: var(--serif); font-size: 14px; line-height: 1.5; color: var(--bone-dim); border-left: 2px solid var(--teal); padding-left: 13px; }
.touch-note span { color: var(--teal); font-family: var(--mono); font-size: 7px; letter-spacing: 0.2em; margin-right: 7px; }
.manual-objective { border-top: 1px solid var(--line); padding-top: 17px; }
.manual-objective p { font-family: var(--serif); font-size: 16px; line-height: 1.5; color: var(--bone-dim); margin: 7px 0 14px; }
.meter-legend { display: flex; gap: 15px; flex-wrap: wrap; }
.meter-legend span { display: flex; align-items: center; gap: 5px; font-size: 5.5px; letter-spacing: 0.12em; color: var(--bone-dim); }
.meter-legend i { width: 5px; height: 5px; border-radius: 50%; display: inline-block; }
.power-dot { background: var(--teal); }
.battery-dot { background: var(--gold); }
.danger-dot { background: var(--red); }
.intel { display: flex; flex-direction: column; min-height: 0; }
.intel-list { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin-top: 12px; overflow-y: auto; padding-right: 4px; }
.intel-card { border: 1px solid var(--line); padding: 13px; background: rgba(233, 225, 207, 0.02); position: relative; }
.intel-card::before { content: ''; position: absolute; left: 0; top: 0; width: 2px; height: 38%; background: var(--red); opacity: 0.7; }
.intel-card h4 { font-family: var(--display); font-weight: 400; font-size: 19px; letter-spacing: 0.08em; margin: 0 0 2px; }
.intel-card .intel-role { font-size: 6px; letter-spacing: 0.16em; color: var(--teal); }
.intel-card p { font-family: var(--serif); font-size: 12.5px; line-height: 1.4; color: var(--bone-dim); margin: 7px 0 0; }
.intel-card b { color: var(--bone); font-weight: 500; }
.intel-card .intel-threat { margin-top: 7px; display: flex; gap: 2px; }
.intel-card .intel-threat i { width: 12px; height: 2px; background: var(--line-strong); display: inline-block; }
.intel-card .intel-threat i.on { background: var(--red); }

/* ============================ HUD ============================ */
.game-hud {
  position: fixed;
  inset: 0;
  z-index: 5;
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.5s;
}
.game-hud.is-visible { opacity: 1; }
.game-hud > * { pointer-events: none; }
.game-hud button { pointer-events: auto; }
.hud-top-left { position: absolute; top: max(20px, env(safe-area-inset-top)); left: max(24px, env(safe-area-inset-left)); display: flex; flex-direction: column; gap: 2px; }
.night-label { display: flex; align-items: center; gap: 7px; font-size: 7px; letter-spacing: 0.2em; color: var(--bone-dim); }
.night-label b { font-family: var(--display); font-size: 17px; font-weight: 400; color: var(--bone); letter-spacing: 0.1em; }
.night-label i { height: 1px; width: 20px; background: var(--line-strong); }
.night-label em { font-style: normal; font-size: 5.5px; color: var(--teal); }
.shift-clock { display: flex; align-items: baseline; gap: 5px; margin: 3px 0 0 -3px; }
.shift-clock b { font-family: var(--display); font-size: clamp(38px, 4.3vw, 58px); font-weight: 400; line-height: 0.9; letter-spacing: 0.03em; color: var(--bone); text-shadow: 0 2px 20px rgba(0, 0, 0, 0.7); }
.shift-clock span { font-size: 9px; letter-spacing: 0.1em; color: var(--bone-dim); }
.hour-dots { display: flex; gap: 5px; margin-top: 4px; }
.hour-dots i { width: 14px; height: 2px; background: rgba(233, 225, 207, 0.15); transition: background 0.4s; }
.hour-dots i.done { background: var(--red); }
.hour-dots i.active { background: var(--bone); box-shadow: 0 0 6px rgba(233, 225, 207, 0.5); }

.hud-top-right { position: absolute; top: max(20px, env(safe-area-inset-top)); right: max(24px, env(safe-area-inset-right)); width: min(260px, 30vw); display: flex; flex-direction: column; gap: 12px; }
.meter-block { border-top: 1px solid var(--line-strong); padding-top: 7px; }
.meter-head { display: flex; justify-content: space-between; align-items: baseline; font-size: 7px; letter-spacing: 0.18em; color: var(--bone-dim); }
.meter-head b { font-family: var(--display); font-size: 22px; font-weight: 400; letter-spacing: 0.04em; color: var(--bone); }
.meter { height: 4px; background: rgba(233, 225, 207, 0.13); margin: 5px 0; overflow: hidden; position: relative; }
.meter i { display: block; height: 100%; width: 100%; background: linear-gradient(90deg, #2e7770, var(--teal)); transition: width 0.25s linear, background 0.4s; }
.meter.small { height: 3px; }
.power-block .meter i.low { background: var(--gold); }
.power-block .meter i.critical { background: var(--red); }
.battery-block .meter i { background: linear-gradient(90deg, #9a7e3d, var(--gold)); }
.battery-block .meter i.low { background: var(--red); }
.usage-bars { display: flex; gap: 3px; margin-top: 4px; }
.usage-bars i { width: 18px; height: 6px; border: 1px solid var(--line-strong); background: transparent; transition: background 0.25s; }
.usage-bars i.on { background: var(--bone); border-color: var(--bone); }
.usage-bars i.warn { background: var(--gold); border-color: var(--gold); }
.meter-sub { display: block; font-size: 5.5px; letter-spacing: 0.14em; color: var(--bone-dim); margin-top: 3px; }
.battery-block .meter-sub { color: var(--teal); }

.event-log { position: absolute; left: max(24px, env(safe-area-inset-left)); bottom: 118px; width: min(380px, 58vw); display: flex; flex-direction: column-reverse; gap: 3px; }
.event-line { font-family: var(--serif); font-size: 12px; letter-spacing: 0.02em; color: rgba(233, 225, 207, 0.67); background: linear-gradient(90deg, rgba(4, 6, 6, 0.65), transparent); padding: 3px 7px 3px 0; animation: eventIn 0.35s var(--ease); text-shadow: 0 1px 3px #000; }
.event-line::before { content: '›'; color: var(--red); margin-right: 7px; font-family: var(--mono); font-size: 8px; }
.event-line.danger { color: var(--bone); }
.event-line.danger::before { color: var(--red-bright); }
@keyframes eventIn { from { opacity: 0; transform: translateX(-7px); } to { opacity: 1; transform: none; } }
.danger-vignette { position: absolute; inset: 0; background: radial-gradient(ellipse at center, transparent 50%, rgba(145, 9, 18, 0.4)); opacity: 0; transition: opacity 0.8s; }
.danger-vignette.on { opacity: 0.9; animation: dangerPulse 1.7s infinite; }
@keyframes dangerPulse { 0%, 100% { opacity: 0.35; } 50% { opacity: 0.8; } }
.red-alert { position: absolute; inset: 0; background: rgba(126, 5, 12, 0.25); opacity: 0; pointer-events: none; }
.red-alert.on { animation: redAlert 0.8s infinite; }
@keyframes redAlert { 0%, 100% { opacity: 0; } 50% { opacity: 0.7; } }

.hud-bottom { position: absolute; left: max(24px, env(safe-area-inset-left)); right: max(24px, env(safe-area-inset-right)); bottom: max(18px, env(safe-area-inset-bottom)); display: flex; align-items: flex-end; justify-content: space-between; }
.door-control { width: 148px; padding: 11px 13px 10px; border: 1px solid var(--line-strong); background: linear-gradient(180deg, rgba(8, 10, 10, 0.8), rgba(8, 10, 10, 0.5)); backdrop-filter: blur(6px); text-align: left; transition: border-color 0.25s, background 0.25s; position: relative; }
.door-control:hover { border-color: var(--bone-dim); }
.door-kicker { font-size: 5.5px; letter-spacing: 0.22em; color: var(--bone-dim); display: block; }
.door-state { display: flex; align-items: center; gap: 7px; margin-top: 5px; }
.door-state i { width: 6px; height: 6px; border-radius: 50%; background: #4e7a60; box-shadow: 0 0 7px rgba(66, 143, 88, 0.45); transition: background 0.2s, box-shadow 0.2s; }
.door-state b { font-family: var(--display); font-size: 23px; font-weight: 400; letter-spacing: 0.1em; color: var(--bone); }
.door-control.closed { border-color: rgba(189, 24, 35, 0.72); background: rgba(80, 7, 12, 0.4); }
.door-control.closed .door-state i { background: var(--red-bright); box-shadow: 0 0 10px rgba(226, 36, 48, 0.7); }
.door-control.closed .door-state b { color: var(--red-bright); }
.door-control.alert { animation: doorAlert 0.7s infinite; }
@keyframes doorAlert { 0%, 100% { box-shadow: none; } 50% { box-shadow: 0 0 0 1px var(--red), 0 0 22px rgba(189, 24, 35, 0.25); } }
.door-key { position: absolute; right: 10px; top: 9px; font-size: 6px; border: 1px solid var(--line); padding: 2px 4px; color: var(--bone-dim); }
.center-controls { display: flex; align-items: flex-end; gap: 13px; }
.round-control { width: 64px; height: 64px; border-radius: 50%; border: 1px solid var(--line-strong); background: rgba(8, 10, 10, 0.68); backdrop-filter: blur(7px); display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 3px; position: relative; transition: border-color 0.2s, background 0.2s, box-shadow 0.2s; }
.round-control svg { width: 25px; height: 25px; color: var(--bone-dim); transition: color 0.2s; }
.round-control > span { font-size: 5.5px; letter-spacing: 0.16em; color: var(--bone-dim); }
.round-control.on { border-color: var(--gold); box-shadow: 0 0 24px rgba(201, 171, 110, 0.16), inset 0 0 18px rgba(201, 171, 110, 0.1); }
.round-control.on svg { color: var(--gold); }
.control-ring { position: absolute; inset: 4px; border: 1px solid transparent; border-radius: 50%; transition: border-color 0.25s; }
.round-control.on .control-ring { border-color: rgba(201, 171, 110, 0.25); }
.camera-control { height: 64px; min-width: 150px; border: 1px solid var(--line-strong); background: rgba(8, 10, 10, 0.68); backdrop-filter: blur(7px); display: flex; align-items: center; gap: 12px; padding: 10px 17px; transition: border-color 0.2s, background 0.2s; }
.camera-control:hover { border-color: var(--bone-dim); background: rgba(20, 24, 23, 0.8); }
.cam-glyph { display: grid; grid-template-columns: 1fr 1fr; gap: 2px; width: 22px; height: 22px; }
.cam-glyph i { border: 1px solid var(--teal); opacity: 0.7; }
.cam-copy { display: flex; flex-direction: column; text-align: left; gap: 2px; }
.cam-copy b { font-family: var(--display); font-size: 17px; font-weight: 400; letter-spacing: 0.11em; }
.cam-copy small { font-size: 5.5px; letter-spacing: 0.12em; color: var(--bone-dim); }
.hud-hint { position: absolute; left: 50%; bottom: 105px; transform: translateX(-50%); display: flex; align-items: center; gap: 8px; border: 1px solid var(--line); background: rgba(6, 8, 8, 0.66); padding: 6px 12px; backdrop-filter: blur(7px); font-family: var(--serif); font-size: 12px; color: var(--bone-dim); opacity: 0; transition: opacity 0.35s, transform 0.35s; white-space: nowrap; }
.hud-hint.show { opacity: 1; transform: translateX(-50%) translateY(-3px); }
.hint-mark { font-family: var(--mono); font-size: 8px; border: 1px solid var(--red); color: var(--red-bright); width: 13px; height: 13px; display: grid; place-items: center; }
.hud-corner { position: absolute; width: 18px; height: 18px; border-color: rgba(233, 225, 207, 0.18); border-style: solid; pointer-events: none; }
.hud-corner.tl { top: 11px; left: 11px; border-width: 1px 0 0 1px; }
.hud-corner.tr { top: 11px; right: 11px; border-width: 1px 1px 0 0; }
.hud-corner.bl { bottom: 11px; left: 11px; border-width: 0 0 1px 1px; }
.hud-corner.br { bottom: 11px; right: 11px; border-width: 0 1px 1px 0; }

/* ============================ CAMERA UI ============================ */
.camera-ui {
  position: fixed;
  inset: 0;
  z-index: 7;
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.45s;
  font-family: var(--mono);
}
.camera-ui.is-visible { opacity: 1; }
.camera-ui::before {
  content: '';
  position: absolute;
  inset: 0;
  border: clamp(15px, 2.6vw, 38px) solid rgba(3, 5, 5, 0.76);
  box-shadow: inset 0 0 120px rgba(0, 0, 0, 0.65);
}
.cam-static {
  position: absolute;
  inset: 0;
  opacity: 0.09;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.75' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
  animation: staticJitter 0.17s steps(3) infinite;
  mix-blend-mode: screen;
}
@keyframes staticJitter { 0% { transform: translate(0, 0); } 33% { transform: translate(-2%, 1%); } 66% { transform: translate(1%, -2%); } 100% { transform: translate(2%, 1%); } }
.cam-scanlines { position: absolute; inset: 0; background: repeating-linear-gradient(180deg, transparent 0, transparent 3px, rgba(0, 0, 0, 0.24) 4px); mix-blend-mode: multiply; opacity: 0.8; }
.cam-roll { position: absolute; left: 0; right: 0; height: 110px; background: linear-gradient(180deg, transparent, rgba(233, 225, 207, 0.028), transparent); animation: camRoll 8s linear infinite; }
@keyframes camRoll { from { top: -20%; } to { top: 110%; } }
.cam-frame { position: absolute; inset: clamp(15px, 2.6vw, 38px); }
.cam-header { position: absolute; left: 0; right: 0; top: 0; display: flex; align-items: flex-start; justify-content: space-between; padding: 18px 20px 45px; background: linear-gradient(180deg, rgba(3, 5, 5, 0.72), transparent); }
.cam-brand { font-size: 8px; letter-spacing: 0.18em; color: var(--bone); display: flex; align-items: center; gap: 8px; }
.cam-brand small { font-size: 5px; color: var(--teal); border-left: 1px solid var(--line); padding-left: 8px; }
.rec-dot { width: 5px; height: 5px; border-radius: 50%; background: var(--red-bright); box-shadow: 0 0 8px var(--red); animation: livePulse 1.4s infinite; }
.cam-feed-id { display: flex; align-items: center; gap: 12px; }
.cam-feed-id span { font-size: 7px; letter-spacing: 0.18em; color: var(--red-bright); border: 1px solid rgba(189, 24, 35, 0.5); padding: 3px 5px; }
.cam-feed-id b { font-family: var(--display); font-weight: 400; font-size: 20px; letter-spacing: 0.12em; color: var(--bone); }
.cam-clock { display: flex; align-items: baseline; gap: 4px; font-size: 11px; letter-spacing: 0.1em; color: var(--bone); }
.cam-clock small { font-size: 6px; color: var(--bone-dim); }
.cam-corner { position: absolute; width: 26px; height: 26px; border-color: rgba(233, 225, 207, 0.4); border-style: solid; z-index: 2; }
.cam-corner.c1 { top: 11px; left: 11px; border-width: 1px 0 0 1px; }
.cam-corner.c2 { top: 11px; right: 11px; border-width: 1px 1px 0 0; }
.cam-corner.c3 { bottom: 11px; left: 11px; border-width: 0 0 1px 1px; }
.cam-corner.c4 { bottom: 11px; right: 11px; border-width: 0 1px 1px 0; }
.cam-side-left { position: absolute; left: 22px; top: 50%; transform: translateY(-50%); display: flex; flex-direction: column; gap: 22px; font-size: 5.5px; line-height: 1.6; letter-spacing: 0.1em; color: rgba(233, 225, 207, 0.45); writing-mode: vertical-rl; }
.cam-side-left .cam-signal { writing-mode: horizontal-tb; }
.cam-side-left b { color: var(--bone); }
.cam-side-right { position: absolute; right: 23px; top: 50%; transform: translateY(-50%); display: flex; flex-direction: column; align-items: flex-end; gap: 9px; font-size: 6px; letter-spacing: 0.15em; color: rgba(233, 225, 207, 0.45); }
.cam-side-right > span:first-child { color: var(--red); }
.cam-timecode { writing-mode: vertical-rl; letter-spacing: 0.2em; font-size: 6px; }
.cam-reticle { position: absolute; left: 50%; top: 50%; width: 46px; height: 46px; transform: translate(-50%, -50%); opacity: 0.23; }
.cam-reticle i { position: absolute; width: 12px; height: 12px; border-color: var(--bone); border-style: solid; }
.cam-reticle i:nth-child(1) { top: 0; left: 0; border-width: 1px 0 0 1px; }
.cam-reticle i:nth-child(2) { top: 0; right: 0; border-width: 1px 1px 0 0; }
.cam-reticle i:nth-child(3) { bottom: 0; left: 0; border-width: 0 0 1px 1px; }
.cam-reticle i:nth-child(4) { bottom: 0; right: 0; border-width: 0 1px 1px 0; }
.cam-warning { position: absolute; top: 78px; right: 20px; font-size: 7px; letter-spacing: 0.2em; color: var(--red-bright); border: 1px solid rgba(189, 24, 35, 0.55); background: rgba(90, 5, 10, 0.45); padding: 4px 7px; opacity: 0; transition: opacity 0.3s; }
.cam-warning.on { opacity: 1; animation: blink 0.9s steps(2) infinite; }
@keyframes blink { 50% { opacity: 0.3; } }
