    this.addBox(.04, 1.1, .05, this.mWhite, 5.0, 1.9, -4.0, null, g, false);
    // hanging pots
    for (let i = 0; i < 6; i++) {
      const x = -5 + i * .72;
      this.addCylinder(.012, .012, .8, this.mDark, x, 2.65, 0, 5, g);
      this.addCylinder(.2, .2, .08, this.mMetal, x, 2.25, 0, 12, g).rotation.x = Math.PI / 2;
