    for (let z = 6.2; z < 14.6; z += .8) {
      [-1.15, 1.15].forEach(x => {
        const rivet = this.addCylinder(.035, .035, .03, this.mBrass, x, 2.15, z, 6, g);
        rivet.rotation.z = Math.PI / 2;
      });
    }
    // cables and dust
    for (let i = 0; i < 3; i++) {
      const c = this.addCylinder(.025, .025, 8, this.mDark, -.8 + i * .7, 2.92, 10, 5, g);
