from pathlib import Path
p=Path('src/world.js')
s=p.read_text()
# unique LED materials
s=s.replace("""      const led = this.addBox(.055, .055, .03, this.mGlowGreen, 0, .27, -.07, null, panel, false);
      if (side < 0) this.ledL = led; else this.ledR = led;""","""      const ledMat = new THREE.MeshStandardMaterial({ color: 0x8effa8, emissive: 0x2b9c4c, emissiveIntensity: 1.5, roughness: .3 });
      const led = this.addBox(.055, .055, .03, ledMat, 0, .27, -.07, null, panel, false);
      if (side < 0) this.ledL = led; else this.ledR = led;""")
# door start open position and stripes attached
s=s.replace("""      const door = this.addBox(.13, 3.12, 2.42, this.mDoor, side * 5.42, 3.72, .6, null, room, true);
      door.userData.side = side < 0 ? 'left' : 'right';
      this.officeDoors[side < 0 ? 'left' : 'right'] = door;
      // hazard stripes on panel
      const stripeMat = new THREE.MeshStandardMaterial({ color: 0x9b842d, roughness: .7 });
      for (let i = 0; i < 5; i++) {
