const { chromium } = require('playwright');
const fs = require('fs');

const configs = [
  { name: 'headless-swiftshader', headless: true, args: ['--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swiftshader'] },
  { name: 'headless-default', headless: true, args: [] },
  { name: 'headed-swiftshader', headless: false, args: ['--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swiftshader'] },
];

(async () => {
  for (const c of configs) {
    let browser;
    try {
      browser = await chromium.launch({ headless: c.headless, args: c.args });
      const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
      const errs = [];
      page.on('console', m => { if (m.type() === 'error') errs.push(m.text()); });
      await page.goto('http://localhost:3002', { waitUntil: 'domcontentloaded', timeout: 30000 });
      await page.waitForTimeout(3500);
      const info = await page.evaluate(() => {
        const k = window.__KIMETSU__;
        const c = document.querySelector('canvas');
        const gl = c && (c.getContext('webgl2') || c.getContext('webgl'));
        return { frame: k?.renderer?.info?.render?.frame, lost: gl ? gl.isContextLost() : 'nogl', renderer: gl ? (()=>{const d=gl.getExtension('WEBGL_debug_renderer_info');return d?gl.getParameter(d.UNMASKED_RENDERER_WEBGL):'unknown'})() : null };
      });
      const t0 = Date.now();
      let shot = 'ok';
      try { await page.screenshot({ path: `/tmp/opencode/test-${c.name}.png`, timeout: 20000 }); } catch (e) { shot = 'FAIL ' + e.message.split('\n')[0]; }
      console.log(c.name, JSON.stringify(info), 'shot:', shot, 'ms:', Date.now()-t0, 'errs:', errs.slice(0,3));
    } catch (e) {
      console.log(c.name, 'LAUNCH FAIL', e.message.split('\n')[0]);
    } finally { if (browser) await browser.close(); }
  }
})();

