const { chromium } = require('playwright');
const KEY = 'kimetus_nightmare_shift_save_v1';
(async () => {
  const browser = await chromium.launch({ headless: true, args: ['--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swiftshader'] });
  const page = await browser.newPage({ viewport: { width: 800, height: 500 }, hasTouch: true });
  await page.addInitScript((key) => localStorage.setItem(key, JSON.stringify({ version:1, unlocked:5, settings:{master:80,music:55,sfx:70,quality:'low',difficulty:'standard',reducedMotion:true,tilt:false}, custom:{ai:{}} })), KEY);
  await page.goto('http://localhost:3002', { waitUntil: 'domcontentloaded' });
  await page.waitForTimeout(3000);
  const measure = async (label) => { await page.waitForTimeout(2500); const v = await page.evaluate(() => new Promise(res => { let n=0; const t0=performance.now(); function tick(){n++; if(performance.now()-t0<4000) requestAnimationFrame(tick); else res(+(n/((performance.now()-t0)/1000)).toFixed(2));} requestAnimationFrame(tick); })); console.log(label, v); };
  console.log('visible lights', await page.evaluate(() => { let n=0; window.__KIMETSU__.world.scene.traverse(o => { if ((o.isPointLight||o.isSpotLight) && o.visible) n++; }); return n; }));
  await measure('baseline');
  await page.evaluate(() => {
    // keep first 12 point lights, hide rest; keep all spotlights
    let i=0; window.__KIMETSU__.world.scene.traverse(o => { if (o.isPointLight) { i++; if (i>12) o.visible=false; } });
  });
  console.log('count now', await page.evaluate(() => { let n=0; window.__KIMETSU__.world.scene.traverse(o => { if ((o.isPointLight||o.isSpotLight) && o.visible) n++; }); return n; }));
  await measure('12 point lights');
  await page.evaluate(() => { window.__KIMETSU__.world.scene.traverse(o => { if (o.isPointLight) o.visible=false; }); });
  await measure('0 point lights');
  await page.evaluate(() => { window.__KIMETSU__.world.scene.traverse(o => { if (o.isSpotLight && o !== window.__KIMETSU__.world.flashlight) o.visible=false; }); });
  await measure('0 points 1 spot');
  await browser.close();
})();

const { chromium } = require('playwright');
const KEY = 'kimetus_nightmare_shift_save_v1';
(async () => {
  const browser = await chromium.launch({ headless: true, args: ['--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swiftshader'] });
  const page = await browser.newPage({ viewport: { width: 800, height: 500 }, hasTouch: true });
  await page.addInitScript((key) => localStorage.setItem(key, JSON.stringify({ version:1, unlocked:5, settings:{master:80,music:55,sfx:70,quality:'low',difficulty:'standard',reducedMotion:true,tilt:false}, custom:{ai:{}} })), KEY);
  await page.goto('http://localhost:3002', { waitUntil: 'domcontentloaded' });
  for (let s = 0; s < 8; s++) {
    await page.waitForTimeout(4000);
    const v = await page.evaluate(() => new Promise(res => { let n=0; const t0=performance.now(); function tick(){n++; if(performance.now()-t0<4000) requestAnimationFrame(tick); else res(+(n/((performance.now()-t0)/1000)).toFixed(2));} requestAnimationFrame(tick); }));
    const frame = await page.evaluate(() => window.__KIMETSU__.renderer.info.render.frame);
    console.log('t+' + ((s+1)*8) + 's fps', v, 'frame', frame);
  }
  await browser.close();
})();

