const { chromium } = require('playwright');
const KEY = 'kimetus_nightmare_shift_save_v1';
(async () => {
  const browser = await chromium.launch({ headless: true, args: ['--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swiftshader'] });
  const page = await browser.newPage({ viewport: { width: 800, height: 500 }, hasTouch: true });
  await page.addInitScript((key) => localStorage.setItem(key, JSON.stringify({ version:1, unlocked:5, settings:{master:80,music:55,sfx:70,quality:'low',difficulty:'standard',reducedMotion:true,tilt:false}, custom:{ai:{}} })), KEY);
  await page.goto('http://localhost:3002', { waitUntil: 'domcontentloaded' });
  await page.waitForTimeout(10000);
  const measure = async (label) => { const v = await page.evaluate(() => new Promise(res => { let n=0; const t0=performance.now(); function tick(){n++; if(performance.now()-t0<3000) requestAnimationFrame(tick); else res(+(n/((performance.now()-t0)/1000)).toFixed(2));} requestAnimationFrame(tick); })); const calls = await page.evaluate(()=>window.__KIMETSU__.renderer.info.render.calls); console.log(label, 'fps', v, 'calls', calls); };
  await measure('baseline');
  // hide all meshes
  await page.evaluate(() => { window.__KIMETSU__.world.scene.traverse(o => { if (o.isMesh || o.isPoints || o.isSprite) o.visible = false; }); });
  await page.waitForTimeout(6000);
  await measure('no meshes');
  // restore, hide only transparent
  await page.evaluate(() => { window.__KIMETSU__.world.scene.traverse(o => { if (o.isMesh || o.isPoints || o.isSprite) o.visible = true; }); });
  await page.waitForTimeout(4000);
  await page.evaluate(() => { window.__KIMETSU__.world.scene.traverse(o => { if ((o.isMesh||o.isPoints||o.isSprite) && (o.material && o.material.transparent)) o.visible = false; }); });
  await page.waitForTimeout(6000);
  await measure('no transparent');
  // restore, hide characters
  await page.evaluate(() => { window.__KIMETSU__.world.scene.traverse(o => { if (o.isMesh || o.isPoints || o.isSprite) o.visible = true; }); Object.values(window.__KIMETSU__.world.characters).forEach(c => c.visible = false); });
  await page.waitForTimeout(5000);
  await measure('no characters');
  await browser.close();
})();

