const { chromium } = require('playwright');
const path = require('path');
const OUT = '/home/runner/work/PlayGround/PlayGround/screenshots';
const KEY = 'kimetus_nightmare_shift_save_v1';
async function shot(page, name) {
  const t = Date.now();
  await page.screenshot({ path: path.join(OUT, name), timeout: 180000 });
  console.log(name, ((Date.now()-t)/1000).toFixed(1)+'s');
}
(async () => {
  const browser = await chromium.launch({ headless: true, args: ['--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swiftshader'] });
  const page = await browser.newPage({ viewport: { width: 960, height: 600 }, hasTouch: false });
  await page.addInitScript((key) => localStorage.setItem(key, JSON.stringify({ version:1, started:true, unlocked:5, lastNight:1, cleared:[1], deaths:0, settings:{master:0,music:0,sfx:0,quality:'low',difficulty:'standard',reducedMotion:true,tilt:false}, custom:{ai:{}} })), KEY);
  page.on('pageerror', e => console.log('PAGEERR', e.message));
  page.on('console', m => { if (m.type()==='error') console.log('CONSOLE', m.text()); });
  await page.goto('http://localhost:3002', { waitUntil: 'domcontentloaded' });
  await page.waitForTimeout(4000);
  await page.click('[data-action="new"]');
  await page.waitForTimeout(7000);
  console.log('phase', await page.evaluate(()=>window.__KIMETSU__.game.phase));
  await shot(page, 'gameplay-office.png');

  // open camera
  await page.keyboard.press('Space');
  await page.waitForTimeout(4000);
  console.log('monitor', await page.evaluate(()=>window.__KIMETSU__.game.monitor), 'cam', await page.evaluate(()=>window.__KIMETSU__.game.activeCam));
  await shot(page, 'camera-stage.png');

  await page.click('[data-cam="dining"]');
  await page.waitForTimeout(4000);
  console.log('cam', await page.evaluate(()=>window.__KIMETSU__.game.activeCam));
  await shot(page, 'camera-dining.png');

  await page.click('[data-cam="vent"]');
  await page.waitForTimeout(4000);
  await shot(page, 'camera-vent.png');

  // close, flashlight + doors for HUD
  await page.keyboard.press('Space');
  await page.waitForTimeout(2000);
  await page.click('#btn-door-left');
  await page.keyboard.down('f');
  await page.waitForTimeout(2500);
  await shot(page, 'office-doors-flashlight.png');
  await page.keyboard.up('f');

  // freeze a jumpscare mid-rush
  await page.evaluate(() => {
    const g = window.__KIMETSU__.game;
    g._beginJumpscare('muzan', 'test');
  });
  await page.waitForTimeout(900);
  await page.evaluate(() => { window.__KIMETSU__.game.phase = 'paused'; });
  await page.waitForTimeout(1500);
  await shot(page, 'jumpscare.png');

  // resume into game over
  await page.evaluate(() => {
    const g = window.__KIMETSU__.game;
    g.phase = 'playing';
    g._beginJumpscare('tanjiro', 'test');
  });
  await page.waitForTimeout(4500);
  console.log('end phase', await page.evaluate(()=>window.__KIMETSU__.game.phase));
  await shot(page, 'game-over.png');

  // retry then force victory
  await page.click('[data-action="retry"]');
  await page.waitForTimeout(7000);
  await page.evaluate(() => {
    const k = window.__KIMETSU__;
    k.game.phase = 'playing';
    k.game.power = 68;
    k.game.camsVisited = new Set(['stage','dining','west','east','kitchen']);
    k.game._victory();
  });
  await page.waitForTimeout(3500);
  console.log('victory phase', await page.evaluate(()=>window.__KIMETSU__.game.phase));
  await shot(page, 'victory.png');

  await browser.close();
})();

