const { chromium } = require('playwright');
const path = require('path');
const OUT = '/home/runner/work/PlayGround/PlayGround/screenshots';
const KEY = 'kimetus_nightmare_shift_save_v1';
(async () => {
  const browser = await chromium.launch({ headless: true, args: ['--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swiftshader'] });
  const page = await browser.newPage({ viewport: { width: 960, height: 600 }, hasTouch: false });
  await page.addInitScript((key) => localStorage.setItem(key, JSON.stringify({ version:1, started:true, unlocked:5, lastNight:1, cleared:[1], deaths:0, settings:{master:0,music:0,sfx:0,quality:'low',difficulty:'standard',reducedMotion:true,tilt:false}, custom:{ai:{}} })), KEY);
  page.on('pageerror', e => console.log('PAGEERR', e.message));
  await page.goto('http://localhost:3002', { waitUntil: 'domcontentloaded' });
  await page.waitForTimeout(4000);
  await page.click('[data-action="new"]');
  await page.waitForTimeout(2500);
  await page.evaluate(() => { window.__KIMETSU__.game.introTimer = 0; });
  await page.waitForTimeout(3000);
  const info = await page.evaluate(() => {
    const k = window.__KIMETSU__; const g = k.game; const w = k.world;
    g.setMonitor(true); g.setCamera('stage');
    Object.keys(w.characters).forEach((id, i) => w.setCharacterPlacement(id, 'stage', i, true));
    g.phase = 'paused';
    const cam = w.securityCamera;
    cam.updateMatrixWorld(); cam.updateProjectionMatrix();
    const out = {};
    Object.entries(w.characters).forEach(([id, c]) => {
      c.updateMatrixWorld();
      const v = c.position.clone().project(cam);
      out[id] = { pos: c.position.toArray().map(n=>+n.toFixed(2)), ndc: v.toArray().map(n=>+n.toFixed(2)), visible: c.visible, scale: c.scale.x };
    });
    return { cam: cam.position.toArray(), fov: cam.fov, aspect: cam.aspect, chars: out };
  });
  console.log(JSON.stringify(info, null, 1));
  await page.waitForTimeout(2000);
  await page.screenshot({ path: path.join(OUT, 'camera-stage-cast.png'), timeout: 180000 });
  await browser.close();
})();

