const { chromium } = require('playwright');
const KEY = 'kimetus_nightmare_shift_save_v1';
(async () => {
  const browser = await chromium.launch({ headless: true, args: ['--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swiftshader'] });
  const page = await browser.newPage({ viewport: { width: 800, height: 500 }, hasTouch: false });
  await page.addInitScript((key) => localStorage.setItem(key, JSON.stringify({ version:1, started:true, unlocked:5, lastNight:1, cleared:[1,2,3,4], deaths:0, settings:{master:0,music:0,sfx:0,quality:'low',difficulty:'standard',reducedMotion:true,tilt:false}, custom:{ai:{}} })), KEY);
  const errs = [];
  page.on('pageerror', e => errs.push('PAGEERR ' + e.message));
  page.on('console', m => { if (m.type()==='error') errs.push('CONSOLE ' + m.text()); });
  await page.goto('http://localhost:3002', { waitUntil: 'domcontentloaded' });
  await page.waitForTimeout(4000);

  async function runNight(night, opts = {}) {
    return page.evaluate(({ night, opts }) => {
      const k = window.__KIMETSU__;
      const w = k.world;
      k.game.abandon();
      k.game.beginNight({ night, difficulty: 'standard', customAI: null, custom: false });
      k.game.introTimer = 0;
      // advance a few frames to leave intro
      for (let i = 0; i < 5; i++) k.game.update(0.05);
      if (opts.closeDoors) { k.game.setDoor('left', true); k.game.setDoor('right', true); }
      if (opts.monitor) k.game.setMonitor(true);
      let steps = 0;
      const events = [];
      while (k.game.phase === 'playing' && steps < 5000) {
        k.game.update(0.05);
        steps++;
      }
      // drive jumpscare to gameover
      let jsteps = 0;
      while (k.game.phase === 'jumpscare' && jsteps < 100) { k.game.update(0.05); jsteps++; }
      return {
        phase: k.game.phase, hour: +k.game.hourFloat.toFixed(2), steps,
        power: Math.round(k.game.power), battery: Math.round(k.game.battery),
        enemy: k.game.jumpscareId, monitor: k.game.monitor, ai: Object.fromEntries(Object.entries(k.game.ai).map(([id,a]) => [id, a.state]))
      };
    }, { night, opts });
  }

  for (const n of [1, 3, 5]) {
    console.log('night', n, JSON.stringify(await runNight(n)));
  }
  console.log('night 1 doors closed', JSON.stringify(await runNight(1, { closeDoors: true })));
  console.log('night 4 monitor', JSON.stringify(await runNight(4, { monitor: true })));
  await page.waitForTimeout(600);
  console.log('errors', errs.slice(0, 10));
  await browser.close();
})();

